vector<int> makeSet(int n, int scale) {
    vector<int> v;
    v.push_back(0);

    if (n % 2 == 1) {
        int m = n / 2;
        for (int i = 1; i <= m; ++i) {
            v.push_back(i * scale);
            v.push_back(-i * scale);
        }
    } else {
